// Alert Level: how much force the military is cleared to use, set from the damage done and the creature's fury.
const destruction = stats.Destruction.value;
const rampage = entities["The Creature"].stats.Rampage.value;

// Damage weighs most: a wrecked city calls for bigger guns.
// Fury adds the rest: an angry creature looks more dangerous than a calm one.
const pressure = destruction * 0.7 + rampage * 0.3;

// The military never stands down. When the creature calms, the alert holds where it stands.
const alertLevel = Math.max(self.previous.value, pressure);

// The stat clamps the result to 0–100.
return Math.round(alertLevel);

// Pursuit: how tightly the military has the creature boxed in. Alert Level says how large the response is.
// Pursuit says how closely it has closed around the creature. It reads the map, so the chase follows the roads.

// 1. Count the roads into the creature's place. Each exit is a way the military can bring units in.
//    A place with no parent holds the whole city, so it is not a road in. Skip it.
const roadsIn = location.exits.filter((exit) => locations[exit.name].parent !== "");

// 2. Check whether the creature held its ground. Last Sighting holds the place the military fixed it at
//    on the turn before. On the first turn it holds "the bay", so the landing counts as a move.
const lastSighting = placeholders["Last Sighting"];
const heldGround = lastSighting.value === location.name;

// 3. Pace the chase. While the creature holds one place, the units close in along every road into it,
//    3 Pursuit for each road each turn. A hub with many roads fills fast, and a dead end with one road
//    fills slowly. A move throws the units off the trail, and half the pursuit must regroup.
const pursuitPerRoad = 3;
const pursuit = heldGround ? self.value + roadsIn.length * pursuitPerRoad : self.value / 2;

// 4. Name the roads the next units take, in the words of the map's travel hints. The units travel from the
//    next place toward the creature, so read the hint on the leg that points back here. A road with no
//    hint names the place it comes from.
const roadNames = roadsIn.map((exit) => {
  const legBack = locations[exit.name].exits.find((back) => back.name === location.name);
  return legBack && legBack.hint ? legBack.hint + " from " + exit.name : "from " + exit.name;
});
const lastRoad = roadNames[roadNames.length - 1];
const roadList = roadNames.length > 1 ? roadNames.slice(0, -1).join(", ") + " and " + lastRoad : lastRoad || "from every side";
placeholders["Pursuit Roads"].pin(roadList);

// 5. Fix the creature's position, for next turn's check.
lastSighting.pin(location.name);

// The stat clamps the result to 0–100.
return Math.round(pursuit);

// Berserk State: starts each frenzy fresh.
// The Berserk stat keeps its value while it is switched off, so a new frenzy would start where the last one stopped.
// When the trait switches on, the stat switches on with it, and this clears it back to zero.
if (trait.enabled) owner.stats.Berserk.value = 0;

// Berserk: how deep the frenzy runs. Berserk State switches this stat on, so this script runs only during a frenzy.
const health = owner.stats.Health;
const rampage = owner.stats.Rampage;

// Each turn of frenzy sinks a quarter of the way deeper, so four turns in a row reach the bottom.
const berserk = Math.min(self.previous.value + self.max * 0.25, self.max);

// How far down the frenzy is, from 0 at the top to 1 at the bottom. The two costs below scale with it.
const depth = berserk / self.max;

// The frenzy feeds the fury: 5 Rampage a turn at the start, up to 15 at the bottom.
rampage.value = rampage.value + 5 + Math.round(depth * 10);

// The wounds stay open: Health loses a share of its max, 4% at the start, up to 10% at the bottom.
// A share of max, not a fixed number, keeps the cost fair on every body (Armored Hide raises the max).
health.value = health.value - Math.round(health.max * (0.04 + depth * 0.06));

// The stat clamps the result to 0–100.
return Math.round(berserk);

