// Log Landmark: the AI calls log_landmark when the narration shows the creature bring down a named landmark.
// The call pins the loss as a memory, adds a landmark bonus to Destruction, and puts the loss at the top of
// Channel 8's stories. The stat pass still scores the smash itself. The bonus here is on top of it.
const landmarkBonus = 5;

// 1. Read the landmark. args.landmark is one of the landmarks this Tool lists.
const landmarkName = String(args.landmark);

// 2. Log each landmark once. The pinned memories hold the landmarks of earlier turns. A memory pinned this
//    turn lands only when the turn ends, so a second call this turn can't see it there. A placeholder pin
//    lands at once, so Top Stories holds this turn's falls, and the check reads both.
const memoryPrefix = "The creature destroyed " + landmarkName + " in ";
const storyLine = "the fall of " + landmarkName;
const topStories = placeholders["Top Stories"];
const loggedBefore = memories.some((memory) => memory.custom && memory.text.startsWith(memoryPrefix));
const loggedThisTurn = topStories.value.includes(storyLine);
if (loggedBefore || loggedThisTurn) {
  return landmarkName + " is already logged. Nothing changed. Give the stat changes.";
}

// 3. Pin the loss as a memory, so every later request carries it. It names where the creature stood,
//    so the ruin stays on the map.
memories.pin(memoryPrefix + location.name + ".");

// 4. Add the landmark bonus. Destruction only climbs, and it stops at its max.
const destruction = stats.Destruction;
destruction.value = Math.min(destruction.value + landmarkBonus, destruction.max);

// 5. Put the loss at the top of Channel 8's stories. The news keeps the three latest falls, newest first.
//    Before the first fall, Top Stories holds the authored stories, which are not falls, so keep only falls.
const earlierFalls = topStories.value.filter((story) => story.startsWith("the fall of "));
topStories.pin([storyLine, ...earlierFalls].slice(0, 3));

// 6. Answer with the new total, so the stat changes and the damage agree.
return "Logged " + landmarkName + ". Destruction is now " + destruction.value + ". Give the stat changes.";
